26	describe("matchesSearch", () => {
27	  it("returns true when query is empty", () => {
28	    const feature = makeFeature();
29	    expect(matchesSearch(feature, "")).toBe(true);
30	  });
31	
32	  it("matches on feature title (case-insensitive)", () => {
33	    const feature = makeFeature({ title: "Authentication System" });
34	    expect(matchesSearch(feature, "auth")).toBe(true);
35	    expect(matchesSearch(feature, "AUTH")).toBe(true);
36	    expect(matchesSearch(feature, "payment")).toBe(false);
37	  });
38	
39	  it("matches on feature id", () => {
