41	    expect(matchesSearch(feature, "dashboard")).toBe(true);
42	    expect(matchesSearch(feature, "xyz")).toBe(false);
43	  });
44	
45	  it("matches on task title", () => {
46	    const feature = makeFeature({
47	      tasks: [makeTask("T1", "Setup OAuth providers", "todo")],
48	    });
49	    expect(matchesSearch(feature, "oauth")).toBe(true);
50	    expect(matchesSearch(feature, "payment")).toBe(false);
51	  });
52	
53	  it("matches on task id", () => {
54	    const feature = makeFeature({
55	      tasks: [makeTask("T7", "Some task", "ready")],
56	    });
57	    expect(matchesSearch(feature, "T7")).toBe(true);
58	    expect(matchesSearch(feature, "T3")).toBe(false);
